# AUTOGENERATED by unit-tester skill
"""Tests for Utility.frame — image processing."""
import pytest
import numpy as np
import sys, os

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "../.."))

from Utility.frame import get_img_from_obs


class TestImports:
    def test_callable(self):
        assert callable(get_img_from_obs)


class TestGetImgFromObs:
    def test_basic(self):
        img = np.arange(24).reshape(2, 3, 4)
        obs = {"agentview_image": img}
        result = get_img_from_obs(obs, "agentview_image")
        assert result.shape == img.shape
        np.testing.assert_array_equal(result, img[::-1, ::-1])

    def test_missing_key_raises(self):
        obs = {"agentview_image": np.zeros((2, 3, 4))}
        with pytest.raises(ValueError, match="not in the observation"):
            get_img_from_obs(obs, "nonexistent_key")

    def test_double_flip_identity(self):
        img = np.random.rand(4, 6, 3)
        obs = {"cam": img}
        result = get_img_from_obs(obs, "cam")
        result2 = result[::-1, ::-1]
        np.testing.assert_array_equal(result2, img)
